typedef struct { char op; int16_t a; uint16_t b; } op_t;
typedef struct { const char *name; uint16_t first; uint16_t count; uint8_t host_only; } scen_t;
#include "scripts.h"

static c2_tx_t g_tx;
static c2_hello_t g_hello;
static c2_window_meta_t g_meta;
static int16_t g_win[150][3];
static int16_t g_smp[16][3];
static uint8_t g_out[256];

static const uint16_t k_ext[12] = {0x8000u, 0x7FFFu, 0xFFFFu, 0x0000u, 0x0001u, 0x00FFu, 0x0100u, 0xFF00u,
                                   0x7F80u, 0x8080u, 0x0080u, 0xFF7Fu};
static const uint16_t k_pat[8] = {0x0080u, 0x8000u, 0x00FFu, 0xFF00u, 0x7F00u, 0x0001u, 0xFFFFu, 0x0180u};
static const uint8_t k_cycle[9] = {32u, 1u, 31u, 33u, 255u, 5u, 0u, 17u, 2u};
static const char k_check[] = "123456789";

/** xorshift32 (13, 17, 5), G. Marsaglia, J. Statistical Software 8(14), 2003; mirrored in oracle.py (Rng).
 * @param s State, updated.
 * @return Next value. */
static uint32_t rnd(uint32_t *s)
{
    uint32_t x = *s;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *s = x;
    return x;
}

/** Fill rows x 3 int16 with a pattern kind; mirrors oracle.fill.
 * @param buf Rows of 3.
 * @param rows Row count.
 * @param k Kind (>= 0 seeded random, -1 extremes, -2 zeros, -3 byte patterns, -4 ramp).
 * @return None. */
static void fill(int16_t (*buf)[3], uint16_t rows, int16_t k)
{
    uint32_t s = ((uint32_t)(uint16_t)(k + 1)) * 0x9E3779B1u;
    for (uint16_t i = 0; i < (uint16_t)(rows * 3u); i++) {
        int16_t v;
        if (k >= 0) {
            v = (int16_t)(uint16_t)(rnd(&s) >> 8);
        } else if (k == -1) {
            v = (int16_t)k_ext[i % 12u];
        } else if (k == -2) {
            v = 0;
        } else if (k == -3) {
            v = (int16_t)k_pat[i % 8u];
        } else {
            v = (int16_t)((int16_t)i * 7 - 400);
        }
        buf[i / 3u][i % 3u] = v;
    }
}

/** Print n bytes as "x <hex>" lines of at most 32 bytes.
 * @param p Bytes.
 * @param n Count.
 * @return None. */
static void print_hex(const uint8_t *p, uint8_t n)
{
    for (uint8_t i = 0; i < n; i++) {
        if ((i & 31u) == 0u) {
            printf("%sx ", i ? "\n" : "");
        }
        printf("%02x", (unsigned)p[i]);
    }
    if (n) {
        printf("\n");
    }
}

/** One c2_tx_pump call with an 0xEE-filled output area; prints the P line and the bytes.
 * @param room Room passed.
 * @param poll Also call c2_tx_take_release afterwards and print it.
 * @return Bytes returned. */
static uint8_t do_pump(uint8_t room, bool poll)
{
    memset(g_out, 0xEE, sizeof g_out);
    uint8_t n = c2_tx_pump(&g_tx, g_out, room);
    unsigned g = 1u;
    for (uint16_t i = n; i < sizeof g_out; i++) {
        if (g_out[i] != 0xEEu) {
            g = 0u;
        }
    }
    printf("P room=%u n=%u busy=%u g=%u", (unsigned)room, (unsigned)n, (unsigned)c2_tx_busy(&g_tx), g);
    if (poll) {
        printf(" rel=%u", (unsigned)c2_tx_take_release(&g_tx));
    }
    printf("\n");
    print_hex(g_out, n);
    return n;
}

/** CRC checks (op C); mirrors oracle.Replay.crc_op.
 * @param a Kind. @param b Argument (data length for kind 3).
 * @return None. */
static void crc_op(int16_t a, uint16_t b)
{
    const uint8_t *c = (const uint8_t *)k_check;
    if (a == 0) {
        printf("C0 %04x\n", (unsigned)c2_crc16_update(0xFFFFu, c, 9u));
    } else if (a == 1) {
        for (uint16_t k = 0; k < 10u; k++) {
            uint16_t x = c2_crc16_update(0xFFFFu, c, k);
            x = c2_crc16_update(x, c + k, (uint16_t)(9u - k));
            printf("C1 k=%u %04x\n", (unsigned)k, (unsigned)x);
        }
    } else if (a == 2) {
        printf("C2 %04x %04x\n", (unsigned)c2_crc16_update(0x1234u, c, 9u),
               (unsigned)c2_crc16_update(0xBEEFu, c, 0u));
    } else {
        uint8_t d[300];
        uint32_t s = (uint32_t)b + 1u;
        for (uint16_t i = 0; i < b; i++) {
            d[i] = (uint8_t)(rnd(&s) >> 9);
        }
        uint16_t whole = c2_crc16_update(0xFFFFu, d, b);
        uint16_t t1 = (uint16_t)(b / 3u), t2 = (uint16_t)(2u * b / 3u);
        uint16_t sp = c2_crc16_update(0xFFFFu, d, t1);
        sp = c2_crc16_update(sp, d + t1, (uint16_t)(t2 - t1));
        sp = c2_crc16_update(sp, d + t2, (uint16_t)(b - t2));
        uint16_t bw = 0xFFFFu;
        for (uint16_t i = 0; i < b; i++) {
            bw = c2_crc16_update(bw, d + i, 1u);
        }
        printf("C3 len=%u whole=%04x split=%04x bytewise=%04x\n", (unsigned)b, (unsigned)whole, (unsigned)sp,
               (unsigned)bw);
    }
}

/** Op Q: n silent frames of one kind, pumped with room 32. Checks the CRC of every frame with
 * c2_crc16_update (byte at a time), hashes header bytes 0..7 (FNV-1a), compares bytes 8..len-3 of
 * every frame with the first one through a CRC, counts take_release trues.
 * @param kind 'H', 'W' or 'S'. @param n Frame count.
 * @return None. */
static void bulk(char kind, uint32_t n)
{
    uint16_t flen = kind == 'H' ? 18u : (kind == 'W' ? 922u : 107u);
    uint32_t hash = 0x811C9DC5u, bytes = 0u, rel = 0u, badcrc = 0u, badlen = 0u, startfail = 0u, diff = 0u;
    uint16_t refcrc = 0u;
    for (uint32_t f = 0; f < n; f++) {
        bool ok = kind == 'H' ? c2_tx_start_hello(&g_tx, &g_hello)
                : (kind == 'W' ? c2_tx_start_window(&g_tx, &g_meta, (const int16_t (*)[3])g_win)
                               : c2_tx_start_samples(&g_tx, (const int16_t (*)[3])g_smp));
        if (!ok) {
            startfail++;
            continue;
        }
        uint16_t pos = 0, crcA = 0xFFFFu, crcB = 0xFFFFu;
        uint8_t last2[2] = {0u, 0u};
        uint16_t guard = 0;
        while (c2_tx_busy(&g_tx) && guard++ < 1000u) {
            uint8_t n2 = c2_tx_pump(&g_tx, g_out, 32u);
            for (uint8_t i = 0; i < n2; i++, pos++) {
                uint8_t b = g_out[i];
                if (pos < 8u) {
                    hash = (hash ^ b) * 0x01000193u;
                }
                if (pos >= 2u && pos < (uint16_t)(flen - 2u)) {
                    crcA = c2_crc16_update(crcA, &b, 1u);
                }
                if (pos >= 8u && pos < (uint16_t)(flen - 2u)) {
                    crcB = c2_crc16_update(crcB, &b, 1u);
                }
                if (pos + 2u >= flen) {
                    last2[pos + 2u - flen] = b;
                }
            }
        }
        bytes += pos;
        if (pos != flen) {
            badlen++;
        }
        if (crcA != (uint16_t)(last2[0] | ((uint16_t)last2[1] << 8))) {
            badcrc++;
        }
        if (f == 0u) {
            refcrc = crcB;
        } else if (crcB != refcrc) {
            diff++;
        }
        if (c2_tx_take_release(&g_tx)) {
            rel++;
        }
    }
    printf("Q kind=%c n=%lu rel=%lu bytes=%lu hash=%08lx diff=%lu badcrc=%lu badlen=%lu startfail=%lu\n",
           kind, (unsigned long)n, (unsigned long)rel, (unsigned long)bytes, (unsigned long)hash,
           (unsigned long)diff, (unsigned long)badcrc, (unsigned long)badlen, (unsigned long)startfail);
}

/** Execute one op; mirrors oracle.Replay.exec.
 * @param o The op.
 * @return None. */
static void exec_op(const op_t *o)
{
    switch (o->op) {
    case 'I':
        c2_tx_init(&g_tx);
        g_hello = g_hello_tab[0];
        g_meta = g_meta_tab[0];
        fill(g_win, 150u, -2);
        fill(g_smp, 16u, -2);
        printf("I\n");
        break;
    case 'h': g_hello = g_hello_tab[o->a]; break;
    case 'm': g_meta = g_meta_tab[o->a]; break;
    case 'f': fill(g_win, 150u, o->a); break;
    case 'g': fill(g_smp, 16u, o->a); break;
    case 'H':
    case 'W':
    case 'S':
    case 'T': {
        bool r;
        if (o->op == 'H') {
            r = c2_tx_start_hello(&g_tx, &g_hello);
        } else if (o->op == 'W') {
            r = c2_tx_start_window(&g_tx, &g_meta, (const int16_t (*)[3])g_win);
        } else if (o->op == 'S') {
            r = c2_tx_start_samples(&g_tx, (const int16_t (*)[3])g_smp);
        } else {
            r = c2_tx_start_text(&g_tx, g_text[o->a]);
        }
        printf("S%c r=%u busy=%u\n", o->op, (unsigned)r, (unsigned)c2_tx_busy(&g_tx));
        break;
    }
    case 'n': {
        bool r;
        switch (o->a) {
        case 0: r = c2_tx_start_hello(&g_tx, NULL); break;
        case 1: r = c2_tx_start_window(&g_tx, NULL, (const int16_t (*)[3])g_win); break;
        case 2: r = c2_tx_start_window(&g_tx, &g_meta, NULL); break;
        case 3: r = c2_tx_start_samples(&g_tx, NULL); break;
        default: r = c2_tx_start_text(&g_tx, NULL); break;
        }
        printf("n %d r=%u busy=%u\n", (int)o->a, (unsigned)r, (unsigned)c2_tx_busy(&g_tx));
        break;
    }
    case 'P': (void)do_pump((uint8_t)o->a, false); break;
    case 'D': {
        uint32_t s = ((uint32_t)(o->b >> 1) * 2654435761u + 7u);
        uint16_t calls = 0, i = 0;
        while (c2_tx_busy(&g_tx) && calls < 3000u) {
            uint8_t room;
            if (o->a > 0) {
                room = (uint8_t)o->a;
            } else if (o->a == -1) {
                room = k_cycle[i % 9u];
            } else {
                room = (uint8_t)(rnd(&s) % 70u);
            }
            (void)do_pump(room, (o->b & 1u) != 0u);
            calls++;
            i++;
        }
        (void)do_pump(7u, (o->b & 1u) != 0u);
        printf("D calls=%u busy=%u\n", (unsigned)calls, (unsigned)c2_tx_busy(&g_tx));
        break;
    }
    case 'E': printf("E r=%u\n", (unsigned)c2_tx_take_release(&g_tx)); break;
    case 'B': printf("B busy=%u\n", (unsigned)c2_tx_busy(&g_tx)); break;
    case 'X': printf("X wid=%u\n", (unsigned)c2_tx_window_id(&g_tx)); break;
    case 'C': crc_op(o->a, o->b); break;
    case 'Z':
        printf("# sizeof(c2_tx_t)=%u\n", (unsigned)sizeof(c2_tx_t));
#ifdef __AVR__
        printf("Z le40=%u\n", (unsigned)(sizeof(c2_tx_t) <= 40u));
#endif
        break;
    case 'Q': bulk((char)o->a, (uint32_t)o->b + 1u); break;
    default: printf("BAD OP\n"); break;
    }
}

/** Run every scenario (host-only ones are skipped on AVR).
 * @return 0. */
int main(void)
{
    sim16_init();
    c2_tx_init(&g_tx);
    for (uint16_t s = 0; s < N_SCEN; s++) {
#ifdef __AVR__
        if (g_scen[s].host_only) {
            continue;
        }
#endif
        printf("== %s\n", g_scen[s].name);
        for (uint16_t i = 0; i < g_scen[s].count; i++) {
            op_t o;
#ifdef __AVR__
            memcpy_P(&o, &g_ops[g_scen[s].first + i], sizeof o);
#else
            o = g_ops[g_scen[s].first + i];
#endif
            exec_op(&o);
        }
    }
    sim16_exit(0);
    return 0;
}
